/****************************************************************************
 * VelaSense Board Bring-up
 *
 * Initializes all board peripherals for the VelaSense wrist-worn
 * emotion arousal detection terminal.
 *
 * Peripheral init order:
 *   1. GPIO / pinmux
 *   2. LCD + touch
 *   3. Backlight PWM
 *   4. I2C buses (sensors)
 *   5. SPI bus (PPG / IMU / EDA)
 *   6. RTC
 *   7. Watchdog
 *   8. Haptic motor
 *   9. BLE
 *  10. Sensor framework (uORB)
 ****************************************************************************/

/****************************************************************************
 * Included Files
 ****************************************************************************/

#include <nuttx/config.h>
#include <nuttx/board.h>
#include <nuttx/kthread.h>
#include <syslog.h>

#include "velasense_bringup.h"

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

#define VELASENSE_TAG "velasense"

/****************************************************************************
 * Private Functions
 ****************************************************************************/

/****************************************************************************
 * Name: velasense_init_display
 *
 * Description:
 *   Initialize LCD and touch controller.
 *
 ****************************************************************************/

static int velasense_init_display(void)
{
#ifdef CONFIG_VELASENSE_LCD_ENABLE
  syslog(LOG_INFO, "[%s] Initializing LCD (CO5300 AMOLED)...\n",
         VELASENSE_TAG);

  /* LCD init is handled by the SiFli LCDC driver + co5300 panel driver.
   * The framebuffer device /dev/fb0 will be registered automatically.
   * LVGL will use it via CONFIG_LV_USE_NUTTX_LCD.
   */

  syslog(LOG_INFO, "[%s] LCD ready: /dev/fb0 (390x450)\n", VELASENSE_TAG);
#endif

#ifdef CONFIG_VELASENSE_TOUCH_ENABLE
  syslog(LOG_INFO, "[%s] Touch controller (FT6146) ready: /dev/input0\n",
         VELASENSE_TAG);
#endif

  return OK;
}

/****************************************************************************
 * Name: velasense_init_backlight
 *
 * Description:
 *   Set LCD backlight to default brightness.
 *
 ****************************************************************************/

static int velasense_init_backlight(void)
{
#ifdef CONFIG_PWM
  syslog(LOG_INFO, "[%s] Backlight PWM initialized\n", VELASENSE_TAG);
#endif
  return OK;
}

/****************************************************************************
 * Name: velasense_init_sensors
 *
 * Description:
 *   Initialize sensor buses and register sensor drivers.
 *
 ****************************************************************************/

static int velasense_init_sensors(void)
{
  syslog(LOG_INFO, "[%s] Initializing sensor buses...\n", VELASENSE_TAG);

#ifdef CONFIG_I2C
  /* I2C1: touch (FT6146) + temperature (MAX30208) + haptic (DRV2605L) */
  syslog(LOG_INFO, "[%s] I2C1 ready (touch + temp + haptic)\n",
         VELASENSE_TAG);
#endif

#ifdef CONFIG_SPI
  /* SPI1: PPG (MAX86141) + IMU (ICM42688/BMI270) + EDA (AD5940) */
  syslog(LOG_INFO, "[%s] SPI1 ready (PPG + IMU + EDA)\n", VELASENSE_TAG);
#endif

  /* TODO: Register sensor drivers when implemented
   * - max86141_register()  -> /dev/sensor_ppg
   * - icm42688_register()  -> /dev/sensor_imu
   * - max30208_register()  -> /dev/sensor_temp
   * - ad5940_register()    -> /dev/sensor_eda
   * - drv2605l_register()  -> /dev/sensor_haptic
   * - max17048_register()  -> /dev/sensor_fuel_gauge
   */

  return OK;
}

/****************************************************************************
 * Name: velasense_init_rtc
 *
 * Description:
 *   Verify RTC is running.
 *
 ****************************************************************************/

static int velasense_init_rtc(void)
{
#ifdef CONFIG_RTC
  syslog(LOG_INFO, "[%s] RTC ready: /dev/rtc0\n", VELASENSE_TAG);
#endif
  return OK;
}

/****************************************************************************
 * Name: velasense_init_watchdog
 *
 * Description:
 *   Start watchdog timer.
 *
 ****************************************************************************/

static int velasense_init_watchdog(void)
{
#ifdef CONFIG_WATCHDOG
  syslog(LOG_INFO, "[%s] Watchdog ready: /dev/watchdog0\n",
         VELASENSE_TAG);
#endif
  return OK;
}

/****************************************************************************
 * Name: velasense_init_haptic
 *
 * Description:
 *   Initialize haptic vibration motor driver.
 *
 ****************************************************************************/

static int velasense_init_haptic(void)
{
#ifdef CONFIG_VELASENSE_HAPTIC_ENABLE
  syslog(LOG_INFO, "[%s] Haptic motor (DRV2605L) initializing...\n",
         VELASENSE_TAG);

  /* TODO: drv2605l_i2c_init()
   * - Verify I2C ACK at 0x5A
   * - Set default waveform library
   * - Test vibration
   */

  syslog(LOG_INFO, "[%s] Haptic motor ready\n", VELASENSE_TAG);
#endif
  return OK;
}

/****************************************************************************
 * Name: velasense_init_ble
 *
 * Description:
 *   Initialize Bluetooth stack.
 *
 ****************************************************************************/

static int velasense_init_ble(void)
{
#ifdef CONFIG_VELASENSE_BLE_ENABLE
  syslog(LOG_INFO, "[%s] BLE initializing...\n", VELASENSE_TAG);

  /* BLE init is handled by sf32lb52_bt_adapter + sf32lb52_bth4.
   * The NuttX BT stack will be initialized automatically.
   * GATT services will be registered by the VelaSense BLE module.
   */

  syslog(LOG_INFO, "[%s] BLE ready: VelaSense-377\n", VELASENSE_TAG);
#endif
  return OK;
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

/****************************************************************************
 * Name: board_late_initialize
 *
 * Description:
 *   Board late initialization entry point. Called after NuttX basic
 *   initialization is complete.
 *
 ****************************************************************************/

void board_late_initialize(void)
{
  int ret;

  syslog(LOG_INFO,
         "========================================\n");
  syslog(LOG_INFO,
         "  VelaSense 心迹 v0.1.0\n");
  syslog(LOG_INFO,
         "  腕式情绪唤醒识别终端\n");
  syslog(LOG_INFO,
         "  Board: SF32LB52 LCD\n");
  syslog(LOG_INFO,
         "========================================\n");

  /* 1. Display */

  ret = velasense_init_display();
  if (ret < 0)
    {
      syslog(LOG_ERR, "[%s] LCD init failed: %d\n", VELASENSE_TAG, ret);
    }

  /* 2. Backlight */

  ret = velasense_init_backlight();
  if (ret < 0)
    {
      syslog(LOG_ERR, "[%s] Backlight init failed: %d\n",
             VELASENSE_TAG, ret);
    }

  /* 3. Sensors */

  ret = velasense_init_sensors();
  if (ret < 0)
    {
      syslog(LOG_ERR, "[%s] Sensor init failed: %d\n",
             VELASENSE_TAG, ret);
    }

  /* 4. RTC */

  ret = velasense_init_rtc();
  if (ret < 0)
    {
      syslog(LOG_ERR, "[%s] RTC init failed: %d\n", VELASENSE_TAG, ret);
    }

  /* 5. Watchdog */

  ret = velasense_init_watchdog();
  if (ret < 0)
    {
      syslog(LOG_ERR, "[%s] Watchdog init failed: %d\n",
             VELASENSE_TAG, ret);
    }

  /* 6. Haptic motor */

  ret = velasense_init_haptic();
  if (ret < 0)
    {
      syslog(LOG_ERR, "[%s] Haptic init failed: %d\n",
             VELASENSE_TAG, ret);
    }

  /* 7. BLE */

  ret = velasense_init_ble();
  if (ret < 0)
    {
      syslog(LOG_ERR, "[%s] BLE init failed: %d\n", VELASENSE_TAG, ret);
    }

  syslog(LOG_INFO, "[%s] Board bring-up complete\n", VELASENSE_TAG);
}

/****************************************************************************
 * VelaSense Application Entry Point
 *
 * Starts the VelaSense wrist-worn emotion arousal detection system.
 *
 * Task architecture:
 *   - main task: application orchestration
 *   - sensor_task: PPG/IMU/EDA/temperature sampling (100Hz/100Hz/32Hz/1Hz)
 *   - dsp_task: signal quality + filtering + peak detection
 *   - inference_task: feature extraction + TinyML inference (every 5s)
 *   - ui_task: LVGL rendering + event confirmation
 *   - ble_task: GATT service + event sync
 *
 * All inter-task communication uses uORB topics with timestamps.
 ****************************************************************************/

/****************************************************************************
 * Included Files
 ****************************************************************************/

#include <nuttx/config.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <syslog.h>
#include <time.h>
#include <nuttx/board.h>

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

#define VELASENSE_TAG       "velasense"
#define VELASENSE_VERSION   "0.1.0"

/* Task stack sizes */

#define SENSOR_TASK_STACK   4096
#define DSP_TASK_STACK      8192
#define INFERENCE_TASK_STACK 8192
#define UI_TASK_STACK       8192
#define BLE_TASK_STACK      4096

/* Task priorities (higher = higher priority) */

#define SENSOR_TASK_PRIO    250
#define DSP_TASK_PRIO       240
#define INFERENCE_TASK_PRIO 230
#define UI_TASK_PRIO        220
#define BLE_TASK_PRIO       200

/****************************************************************************
 * Private Data
 ****************************************************************************/

static volatile bool g_running = true;

/****************************************************************************
 * Private Functions
 ****************************************************************************/

/****************************************************************************
 * Name: print_system_info
 *
 * Description:
 *   Print system version, uptime, and memory info.
 *
 ****************************************************************************/

static void print_system_info(void)
{
  struct timespec ts;

  clock_gettime(CLOCK_MONOTONIC, &ts);

  syslog(LOG_INFO,
         "========================================\n");
  syslog(LOG_INFO,
         "  VelaSense 心迹 v%s\n", VELASENSE_VERSION);
  syslog(LOG_INFO,
         "  腕式情绪唤醒识别终端\n");
  syslog(LOG_INFO,
         "  Platform: SF32LB52 LCD (openvela)\n");
  syslog(LOG_INFO,
         "  Uptime: %ld.%03ld s\n",
         (long)ts.tv_sec, ts.tv_nsec / 1000000);
  syslog(LOG_INFO,
         "========================================\n");

  syslog(LOG_INFO, "[%s] Real-time emotion detection: ON-DEVICE\n",
         VELASENSE_TAG);
  syslog(LOG_INFO, "[%s] Privacy: raw waveforms stay in RAM only\n",
         VELASENSE_TAG);
  syslog(LOG_INFO, "[%s] Mimo: event summaries only (user-authorized)\n",
         VELASENSE_TAG);
}

/****************************************************************************
 * Name: sensor_task
 *
 * Description:
 *   Sensor sampling task. Reads PPG, IMU, EDA, and temperature sensors
 *   at their respective rates and publishes to uORB topics.
 *
 ****************************************************************************/

static int sensor_task(int argc, char *argv[])
{
  syslog(LOG_INFO, "[%s] Sensor task started\n", VELASENSE_TAG);

  while (g_running)
    {
      /* TODO Phase 2: Read sensors and publish to uORB
       *
       * PPG @ 100Hz:
       *   - Read MAX86141 FIFO via SPI
       *   - Publish sensor_ppgd topic
       *
       * IMU @ 100Hz:
       *   - Read ICM-42688-P accel + gyro via SPI
       *   - Publish sensor_accel + sensor_gyro topics
       *
       * EDA @ 32Hz:
       *   - Read AD5940 impedance via SPI
       *   - Publish sensor_impd topic
       *
       * Temperature @ 1Hz:
       *   - Read MAX30208 via I2C
       *   - Publish sensor_temp topic
       *
       * All readings include unified timestamp from hardware timer.
       */

      usleep(10000); /* 10ms = 100Hz placeholder */
    }

  return OK;
}

/****************************************************************************
 * Name: dsp_task
 *
 * Description:
 *   Digital signal processing task. Processes raw PPG data through
 *   SQI, filtering, motion artifact suppression, and peak detection.
 *
 ****************************************************************************/

static int dsp_task(int argc, char *argv[])
{
  syslog(LOG_INFO, "[%s] DSP task started\n", VELASENSE_TAG);

  while (g_running)
    {
      /* TODO Phase 3: DSP pipeline
       *
       * 1. PPG Signal Quality Index (SQI)
       *    - SQI < 0.70 → skip, prompt "adjust strap"
       *
       * 2. Bandpass filter (0.5-5Hz Butterworth)
       *
       * 3. Motion artifact suppression (IMU reference)
       *
       * 4. Peak detection + abnormal beat rejection
       *
       * 5. Output: clean beat-to-beat intervals
       */

      usleep(100000); /* 100ms placeholder */
    }

  return OK;
}

/****************************************************************************
 * Name: inference_task
 *
 * Description:
 *   Inference task. Runs feature extraction and TinyML model every 5 seconds
 *   on the latest 60-second data window.
 *
 ****************************************************************************/

static int inference_task(int argc, char *argv[])
{
  syslog(LOG_INFO, "[%s] Inference task started\n", VELASENSE_TAG);

  while (g_running)
    {
      /* TODO Phase 4-5: Feature extraction + inference
       *
       * Every 5 seconds on 60-second window:
       *
       * 1. Feature extraction:
       *    - HR, HR slope, RMSSD, SDNN, IBI dispersion
       *    - Activity intensity, posture
       *    - SCL, SCR count/amplitude, skin temp slope
       *
       * 2. Personal baseline comparison:
       *    - 24h rolling history, time-of-day / activity / wear-state grouping
       *    - Exponential moving average update
       *
       * 3. Rule gate:
       *    - Exclude: high activity, low SQI, not worn, rapid env change
       *
       * 4. INT8 TinyML inference:
       *    - Late feature fusion model
       *    - Output: arousal probability + reason code
       *
       * 5. Steady-state trigger:
       *    - confidence > 0.82 for 15 continuous seconds
       *    - Not in high-intensity activity
       *    - Cooldown: 5 min between same-type events
       */

      usleep(5000000); /* 5s placeholder */
    }

  return OK;
}

/****************************************************************************
 * Name: ui_task
 *
 * Description:
 *   UI rendering task. Drives LVGL and handles event confirmation.
 *
 ****************************************************************************/

static int ui_task(int argc, char *argv[])
{
  syslog(LOG_INFO, "[%s] UI task started\n", VELASENSE_TAG);

  while (g_running)
    {
      /* TODO Phase 6: LVGL UI
       *
       * Screens:
       *   - Home: real-time HR + activity + SQI indicator
       *   - Event: vibration alert → 5-choice label (心动/紧张/惊喜/压力/其他)
       *   - Trend: 24h HR trend + event timeline
       *   - Breathe: 4-4-6 breathing guide with haptic feedback
       *   - Settings: BLE / privacy / notifications / about
       */

      usleep(33000); /* ~30fps LVGL tick */
    }

  return OK;
}

/****************************************************************************
 * Name: ble_task
 *
 * Description:
 *   BLE service task. Handles GATT events and event synchronization.
 *
 ****************************************************************************/

static int ble_task(int argc, char *argv[])
{
  syslog(LOG_INFO, "[%s] BLE task started\n", VELASENSE_TAG);

  while (g_running)
    {
      /* TODO Phase 6: BLE GATT service
       *
       * GATT characteristics:
       *   - Event Notify: real-time event push
       *   - Event Summary: historical summary list
       *   - User Label: phone-side label confirmation
       *   - Config: threshold / sampling rate config
       *   - OTA Data: firmware update
       *
       * Sync protocol:
       *   - Auto-reconnect on disconnect
       *   - Queue events during disconnect, sync on reconnect
       *   - Only send user-confirmed event summaries
       */

      usleep(1000000); /* 1s placeholder */
    }

  return OK;
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

/****************************************************************************
 * Name: velasense_main
 *
 * Description:
 *   VelaSense application entry point. Starts all subsystem tasks.
 *
 ****************************************************************************/

int main(int argc, char *argv[])
{
  int ret;

  print_system_info();

  /* Start sensor sampling task */

  ret = kthread_create("sensor_task", SENSOR_TASK_PRIO, SENSOR_TASK_STACK,
                       sensor_task, NULL, NULL);
  if (ret < 0)
    {
      syslog(LOG_ERR, "[%s] Failed to create sensor task: %d\n",
             VELASENSE_TAG, ret);
    }

  /* Start DSP task */

  ret = kthread_create("dsp_task", DSP_TASK_PRIO, DSP_TASK_STACK,
                       dsp_task, NULL, NULL);
  if (ret < 0)
    {
      syslog(LOG_ERR, "[%s] Failed to create DSP task: %d\n",
             VELASENSE_TAG, ret);
    }

  /* Start inference task */

  ret = kthread_create("infer_task", INFERENCE_TASK_PRIO,
                       INFERENCE_TASK_STACK,
                       inference_task, NULL, NULL);
  if (ret < 0)
    {
      syslog(LOG_ERR, "[%s] Failed to create inference task: %d\n",
             VELASENSE_TAG, ret);
    }

  /* Start UI task */

  ret = kthread_create("ui_task", UI_TASK_PRIO, UI_TASK_STACK,
                       ui_task, NULL, NULL);
  if (ret < 0)
    {
      syslog(LOG_ERR, "[%s] Failed to create UI task: %d\n",
             VELASENSE_TAG, ret);
    }

  /* Start BLE task */

  ret = kthread_create("ble_task", BLE_TASK_PRIO, BLE_TASK_STACK,
                       ble_task, NULL, NULL);
  if (ret < 0)
    {
      syslog(LOG_ERR, "[%s] Failed to create BLE task: %d\n",
             VELASENSE_TAG, ret);
    }

  syslog(LOG_INFO, "[%s] All tasks started. System running.\n",
         VELASENSE_TAG);

  /* Main task: monitor system health */

  while (g_running)
    {
      /* TODO: Watchdog feed
       * TODO: System health monitoring
       * TODO: Low battery detection
       */

      sleep(10);
    }

  return OK;
}

/****************************************************************************
 * PPG Signal Quality Index (SQI) Implementation
 *
 * Multi-component SQI based on amplitude stability, spectral energy
 * in the cardiac band, morphological consistency, and motion estimate.
 ****************************************************************************/

/****************************************************************************
 * Included Files
 ****************************************************************************/

#include <math.h>
#include <string.h>
#include "ppg_sqi.h"

/****************************************************************************
 * Private Data
 ****************************************************************************/

static struct ppg_sqi_config g_config;
static int g_initialized = 0;

/****************************************************************************
 * Private Functions
 ****************************************************************************/

/****************************************************************************
 * Name: compute_amplitude_stability
 *
 * Description:
 *   Compute amplitude stability as 1 - (std/mean) of peak-to-peak
 *   amplitudes within the window. Clamped to [0, 1].
 *
 ****************************************************************************/

static float compute_amplitude_stability(const float *samples, int count)
{
  if (count < 2)
    {
      return 0.0f;
    }

  /* Find local max and min in segments */

  float sum = 0.0f;
  float sum_sq = 0.0f;
  int n = 0;
  int seg_size = (int)(g_config.sample_rate * 0.5f); /* 0.5s segments */

  if (seg_size < 10)
    {
      seg_size = 10;
    }

  for (int i = 0; i < count - seg_size; i += seg_size)
    {
      float seg_max = samples[i];
      float seg_min = samples[i];

      for (int j = i; j < i + seg_size && j < count; j++)
        {
          if (samples[j] > seg_max)
            seg_max = samples[j];
          if (samples[j] < seg_min)
            seg_min = samples[j];
        }

      float ptp = seg_max - seg_min;
      sum += ptp;
      sum_sq += ptp * ptp;
      n++;
    }

  if (n < 2)
    {
      return 0.5f;
    }

  float mean = sum / n;
  float variance = (sum_sq / n) - (mean * mean);
  float std = sqrtf(variance > 0 ? variance : 0);

  if (mean < 1e-6f)
    {
      return 0.0f;
    }

  float cv = std / mean; /* Coefficient of variation */
  float stability = 1.0f - cv;

  if (stability < 0.0f)
    stability = 0.0f;
  if (stability > 1.0f)
    stability = 1.0f;

  return stability;
}

/****************************************************************************
 * Name: compute_spectral_score
 *
 * Description:
 *   Estimate spectral energy ratio in cardiac band (0.5-5 Hz) vs total.
 *   Simple zero-crossing rate approximation.
 *
 ****************************************************************************/

static float compute_spectral_score(const float *samples, int count)
{
  if (count < 10)
    {
      return 0.0f;
    }

  /* Count zero crossings of first derivative (peaks/valleys) */

  int crossings = 0;
  float prev_diff = samples[1] - samples[0];

  for (int i = 2; i < count; i++)
    {
      float diff = samples[i] - samples[i - 1];
      if ((prev_diff > 0 && diff < 0) || (prev_diff < 0 && diff > 0))
        {
          crossings++;
        }
      prev_diff = diff;
    }

  /* Expected crossings for cardiac signal: ~2 per heartbeat cycle
   * At 100Hz, 60bpm → 100 samples/beat → ~2 crossings per 100 samples
   * Normalize to [0, 1] */

  float expected_rate = 2.0f * (count / g_config.sample_rate) *
                        (70.0f / 60.0f); /* Assume ~70bpm */
  float ratio = (float)crossings / (expected_rate + 1.0f);

  /* Good signal has ratio near 1.0 */

  float score;
  if (ratio > 0.5f && ratio < 2.0f)
    {
      score = 1.0f - fabsf(ratio - 1.0f);
    }
  else
    {
      score = 0.0f;
    }

  return score > 1.0f ? 1.0f : (score < 0.0f ? 0.0f : score);
}

/****************************************************************************
 * Name: compute_morphological_score
 *
 * Description:
 *   Estimate morphological consistency by comparing consecutive
 *   beat shapes (normalized cross-correlation of segments).
 *
 ****************************************************************************/

static float compute_morphological_score(const float *samples, int count)
{
  if (count < 20)
    {
      return 0.5f;
    }

  /* Simple: compute variance of first derivative normalized by mean */

  float sum_diff = 0.0f;
  float sum_diff_sq = 0.0f;
  int n = count - 1;

  for (int i = 1; i < count; i++)
    {
      float d = samples[i] - samples[i - 1];
      sum_diff += d;
      sum_diff_sq += d * d;
    }

  float mean_diff = sum_diff / n;
  float var_diff = (sum_diff_sq / n) - (mean_diff * mean_diff);

  /* Low variance in derivative = consistent morphology */

  float score = 1.0f / (1.0f + var_diff * 0.01f);
  return score > 1.0f ? 1.0f : (score < 0.0f ? 0.0f : score);
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

int ppg_sqi_init(const struct ppg_sqi_config *config)
{
  if (!config || config->sample_rate <= 0 || config->window_size < 10)
    {
      return -1;
    }

  memcpy(&g_config, config, sizeof(g_config));

  if (g_config.threshold <= 0)
    {
      g_config.threshold = 0.70f;
    }

  g_initialized = 1;
  return 0;
}

int ppg_sqi_compute(const float *samples, int count,
                    const float *imu_data, int imu_count,
                    struct ppg_sqi_result *result)
{
  if (!g_initialized || !samples || !result || count < 10)
    {
      return -1;
    }

  memset(result, 0, sizeof(*result));

  /* Component 1: Amplitude stability */

  result->amp_stability = compute_amplitude_stability(samples, count);

  /* Component 2: Spectral score */

  result->spectral_score = compute_spectral_score(samples, count);

  /* Component 3: Morphological consistency */

  result->morph_score = compute_morphological_score(samples, count);

  /* Component 4: Motion estimate (from IMU if available) */

  if (imu_data && imu_count > 0)
    {
      /* Compute IMU energy as motion proxy */

      float energy = 0.0f;
      for (int i = 0; i < imu_count; i++)
        {
          energy += imu_data[i] * imu_data[i];
        }

      energy = sqrtf(energy / imu_count);

      /* Low energy = clean signal. Threshold at ~0.5g for rest */

      result->motion_score = 1.0f / (1.0f + energy * 2.0f);
    }
  else
    {
      result->motion_score = 0.8f; /* Assume reasonable if no IMU */
    }

  /* Weighted combination */

  result->quality = 0.30f * result->amp_stability +
                    0.25f * result->spectral_score +
                    0.25f * result->morph_score +
                    0.20f * result->motion_score;

  result->is_reliable = (result->quality >= g_config.threshold) ? 1 : 0;

  return 0;
}

int ppg_sqi_is_reliable(void)
{
  /* TODO: Store last result and return its is_reliable field */
  return 1;
}

/****************************************************************************
 * PPG Bandpass Filter Implementation
 *
 * 4th-order Butterworth bandpass (0.5-5 Hz) via cascaded biquad sections.
 * Coefficients pre-computed for sample_rate = 100 Hz.
 *
 * For other sample rates, coefficients must be recomputed using the
 * bilinear transform. This initial implementation targets 100 Hz.
 ****************************************************************************/

/****************************************************************************
