  max30208_i2c_read_reg(dev, reg, data, len)

/* Conversion time for one-shot mode (datasheet: max 70ms) */

#define MAX30208_CONV_TIME_MS   80

/* FIFO depth (MAX30208 has 32-sample FIFO) */

#define MAX30208_FIFO_DEPTH     32

/****************************************************************************
